head.script:
//
  (function () {
    var p = location.pathname, q = location.search || '', h = location.hash || '';
    var to = 'https://www.decisionlabx.com/';
    if (/^\/p\/install\.html/.test(p)) to = 'https://www.decisionlabx.com/p/install.html' + q + h;   // 구매자 편집기 「설치 안내」 (?blog=&id=) 그대로
    else if (/^\/p\/pricing\.html/.test(p)) to = 'https://www.decisionlabx.com/#pricing';
    else if (/^\/p\/faq\.html/.test(p)) to = 'https://www.decisionlabx.com/#services';
    else if (/^\/p\/contact\.html/.test(p)) to = 'https://www.decisionlabx.com/#contact';
    else if (h && /^#(pricing|goods|ads)/.test(h)) to = 'https://www.decisionlabx.com/' + (h === '#goods' ? '#ads' : h);
    location.replace(to);
  })();
  //
